package io.github.chronicle.core.client.testing;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import io.github.chronicle.core.ChronicleCore;
import io.github.chronicle.core.client.CatalogAddPopup;
import io.github.chronicle.core.client.CoreMenuScreen;
import io.github.chronicle.core.client.EncounterEditorScreen;
import io.github.chronicle.core.client.EventEditorScreen;
import io.github.chronicle.core.menu.CoreMenuModel.Page;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.fabricmc.fabric.api.client.message.v1.ClientReceiveMessageEvents;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.screen.AccessibilityOnboardingScreen;
import net.minecraft.client.gui.screen.TitleScreen;
import net.minecraft.client.gui.screen.multiplayer.ConnectScreen;
import net.minecraft.client.network.ServerAddress;
import net.minecraft.client.network.ServerInfo;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.gui.widget.TextFieldWidget;
import net.minecraft.client.util.ScreenshotRecorder;
import java.nio.file.*;
import java.util.*;

/** Minimal client driver for the opt-in encounter runtime fixture. */
public final class EncounterActionsSmoke {
    private static final String OUTPUT=System.getenv("CHRONICLE_ENCOUNTERS_SMOKE"),ROOT=System.getenv("CHRONICLE_ENCOUNTERS_SERVER_DIR"),PHASE=System.getenv("CHRONICLE_ENCOUNTERS_PHASE"),ADDRESS="127.0.0.1:25575";
    private final Path output,root;private final List<String> messages=new ArrayList<>();private final long began=System.nanoTime();private boolean connecting,sent,maintenanceSent,openerSent,done;private int warmup,step,frames;
    private EncounterActionsSmoke(){output=Path.of(OUTPUT).toAbsolutePath().normalize();root=Path.of(ROOT).toAbsolutePath().normalize();if(!Files.isRegularFile(root.resolve(".encounter-actions-fixture"))||output.startsWith(root)||root.getParent()==null||!root.getParent().getFileName().toString().equals("test-runs")||!List.of("preflight","footprint","invalid_geometry","wide_runtime","basic","restart","ui_wide","ui_compact","uncertain_review","blocked_retry","blocked_skip","region_ground","region_then_point","region_shared","region_blocked","mixed_resolved","mixed_reviewed","seed_zero","resume_zero","seed_multiple","resume_multiple","legacy_retry","changed_target").contains(PHASE))throw new IllegalArgumentException("unsafe encounter smoke fixture");}
    public static void register(){if(OUTPUT==null)return;try{var fixture=new EncounterActionsSmoke();ClientReceiveMessageEvents.GAME.register((message,overlay)->{if(!overlay)fixture.messages.add(message.getString());});ClientTickEvents.END_CLIENT_TICK.register(fixture::tick);}catch(Exception failure){ChronicleCore.LOGGER.error("Encounter smoke setup failed",failure);}}
    private void tick(MinecraftClient client){if(done)return;try{if(System.nanoTime()-began>240_000_000_000L)throw new IllegalStateException("encounter smoke timeout at "+step);for(String message:messages)if(message.contains("Encounter trial FAIL"))throw new IllegalStateException(message);if(client.player==null&&client.getOverlay()==null&&client.currentScreen instanceof AccessibilityOnboardingScreen)client.setScreen(new TitleScreen());if(!connecting&&client.player==null&&client.getOverlay()==null&&client.currentScreen instanceof TitleScreen){connecting=true;ConnectScreen.connect(client.currentScreen,client,ServerAddress.parse(ADDRESS),new ServerInfo("Encounter smoke",ADDRESS,ServerInfo.ServerType.OTHER),false,null);return;}if(client.player==null)return;client.getToastManager().clear();if(PHASE.startsWith("ui_")){ui(client);return;}if(PHASE.equals("uncertain_review")){reviewUi(client);return;}if(PHASE.startsWith("blocked_")){blockedUi(client);return;}if(!sent&&++warmup>=40){sent=true;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial "+PHASE);}if(messages.stream().noneMatch(message->message.contains("Encounter trial PASS "+PHASE)))return;if(PHASE.equals("basic")||PHASE.equals("restart")){if(!maintenanceSent){maintenanceSent=true;client.player.networkHandler.sendChatCommand("chronicle maintenance events");return;}if(messages.stream().noneMatch(message->message.contains("Completed records archived:")))return;finish(client,true,"bounded spawn, at-most-once checks, and production maintenance command routing passed");return;}if(PHASE.equals("wide_runtime")){if(!openerSent){openerSent=true;client.player.networkHandler.sendChatCommand("chronicle encounters");return;}if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.ENCOUNTER_GROUPS)return;finish(client,true,"two exact wide-mob UUIDs completed and archived; canonical encounter catalog opener routed correctly");return;}if(List.of("region_ground","region_then_point","region_shared","region_blocked","mixed_resolved","mixed_reviewed","seed_zero","resume_zero","seed_multiple","resume_multiple","legacy_retry","changed_target").contains(PHASE)){finish(client,true,"bounded Region/saved-plan production runtime checks passed: "+PHASE);return;}finish(client,true,PHASE.equals("preflight")?"blocked later candidate refused with zero claims or entities":PHASE.equals("footprint")?"wide mob crossing an unloaded chunk was refused without claims, spawns, or forced chunks":"deterministic overlap was refused before Event execution, holds, or encounter operations");}catch(Throwable failure){finish(client,false,failure.getClass().getSimpleName()+": "+failure.getMessage());}}

    private void blockedUi(MinecraftClient client){switch(step){
        case 0->{if(++warmup<40)return;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial "+PHASE);step++;}
        case 1->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS blocked_seed")))return;client.player.networkHandler.sendChatCommand("chronicle");step++;}
        case 2->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.triggerForTest("Events"),"Events navigation unavailable for retained plan");step++;}
        case 3->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.EVENTS)return;var entry=menu.state().entries().stream().filter(value->value.id().equals("cue:test:encounter_event")).findFirst().orElse(null);if(entry==null)return;menu.selectForTest(entry.id());step++;}
        case 4->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().detail()==null)return;if(menu.debugForTest())menu.toggleDebugForTest();require(menu.state().phase().equals("PAUSED"),"blocked review is not paused");require(menu.state().detail().description().contains("blocked")&&menu.state().detail().description().contains("minecraft:overworld"),"actionable blocked reason/coordinates missing with Debug off");capture(client,PHASE+"-retained-plan.png");if(PHASE.equals("blocked_retry")){client.player.networkHandler.sendChatCommand("chronicle_encounters_trial recovery_clear");step=10;}else{require(menu.triggerForTest("Review retained encounter plan"),"retained-plan review action unavailable");step++;}}
        case 5->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.triggerForTest("Skip remaining encounter spawns"),"review did not expose skip");require(menu.triggerForTest("Confirm: Skip remaining encounter spawns"),"skip confirmation unavailable");step=12;}
        case 10->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS recovery_clear")))return;if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.triggerForTest("Retry exact encounter plan"),"paused exact retry unavailable");require(menu.triggerForTest("Confirm: Retry exact encounter plan"),"exact retry confirmation unavailable");step=12;}
        case 12->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial recovery_resume");step++;}
        case 13->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS "+PHASE)))return;finish(client,true,PHASE.equals("blocked_retry")?"blocked OPEN/all-PLANNED evidence survived refusal; paused production retry cleared its latch only after exact-space preflight, then completed unchanged UUIDs":"paused production review confirmed skip with CANCELLED exact stages; parent completed and no planned entity spawned");}
        default->throw new IllegalStateException("unexpected blocked recovery step");}}

    private void reviewUi(MinecraftClient client){switch(step){
        case 0->{if(++warmup<40)return;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial uncertain");step++;}
        case 1->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS uncertain_seed")))return;client.player.networkHandler.sendChatCommand("chronicle");step++;}
        case 2->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.triggerForTest("Events"),"Events navigation unavailable for recovery");step++;}
        case 3->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.EVENTS)return;var entry=menu.state().entries().stream().filter(value->value.id().equals("cue:test:encounter_event")).findFirst().orElse(null);if(entry==null)return;menu.selectForTest(entry.id());step++;}
        case 4->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().detail()==null)return;require(menu.state().detail().facts().stream().anyMatch(fact->fact.label().equals("Entity UUID")&&fact.value().contains("CLAIMED")),"exact claimed UUID evidence is not visible");require(menu.triggerForTest("Review uncertain encounter result"),"encounter review action unavailable");step++;}
        case 5->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.triggerForTest("Accept current encounter result"),"review did not expose exact acceptance");require(menu.triggerForTest("Confirm: Accept current encounter result"),"acceptance confirmation unavailable");step++;}
        case 6->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS uncertain_review")))return;finish(client,true,"claimed-missing hold was explicitly reviewed; no entity replay occurred and parent Event completed");}
        default->throw new IllegalStateException("unexpected encounter review step");}}

    private void ui(MinecraftClient client){
        String group="test:"+PHASE;
        switch(step){
            case 0->{if(++warmup<40)return;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial ui_prepare");step++;}
            case 1->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS ui_prepare")))return;client.player.networkHandler.sendChatCommand("chronicle");step++;}
            case 2->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;if(!menu.triggerForTest("Encounter groups")){menu.triggerForTest("v");return;}step++;}
            case 3->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.ENCOUNTER_GROUPS)return;var widgets=menu.visibleWidgetBoundsForTest();var creators=widgets.stream().filter(widget->widget.label().equals("Create encounter group")).toList();require(creators.size()==1,"Create encounter group must appear once above the list");var first=widgets.stream().filter(widget->widget.label().equals(menu.state().entries().getFirst().label())).findFirst().orElseThrow();require(creators.getFirst().y()<first.y(),"Create encounter group is not above existing groups");require(menu.triggerForTest("Create encounter group"),"Create encounter group unavailable");step++;}
            case 4->{if(!(client.currentScreen instanceof EncounterEditorScreen editor))return;require(editor.valuesForTest().id().startsWith("chronicle_core:encounter_"),"new group did not receive a generated ID");editor.setDraftForTest("id",group);editor.setDraftForTest("label","UI patrol");editor.setDraftForTest("description","Native group editor proof");frames=0;step=40;}
            case 40->{if(!(client.currentScreen instanceof EncounterEditorScreen editor))return;if(++frames<4)return;capture(client,PHASE+"-basics.png");require(editor.pressForTest(">"),"Members navigation unavailable");step=5;}
            case 5->{if(!(client.currentScreen instanceof EncounterEditorScreen editor)||!editor.pageForTest().equals("MEMBERS"))return;require(pressPrefix(editor,"Add entity"),"member catalog unavailable");frames=0;step++;}
            case 6->{if(!(client.currentScreen instanceof CatalogAddPopup popup))return;if(++frames==4)capture(client,PHASE+"-member-catalog.png");if(frames<4)return;select(popup,"minecraft:villager");if(client.currentScreen instanceof EncounterEditorScreen)step++;}
            case 7->{if(!(client.currentScreen instanceof EncounterEditorScreen editor))return;require(editor.valuesForTest().members().stream().anyMatch(member->member.entityType().equals("minecraft:villager")),"villager member was not selected");require(editor.pressForTest(">"),"Spawn navigation unavailable");step++;}
            case 8->{if(!(client.currentScreen instanceof EncounterEditorScreen editor)||!editor.pageForTest().equals("SPAWN"))return;require(pressSuffix(editor,"Point"),"Point target choice unavailable");require(pressPrefix(editor,"Choose point"),"Point catalog unavailable");step++;}
            case 9->{if(!(client.currentScreen instanceof CatalogAddPopup popup))return;select(popup,"encounter_trial_point");if(client.currentScreen instanceof EncounterEditorScreen)step++;}
            case 10->{if(!(client.currentScreen instanceof EncounterEditorScreen editor))return;require(editor.valuesForTest().current(),"Point target did not retain its exact revision");require(editor.pressForTest("Create group"),"Create group unavailable");step++;}
            case 11->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending())return;require(menu.state().entries().stream().anyMatch(entry->entry.id().equals(group)),"created encounter group missing from catalog");require(menu.triggerForTest("Events"),"Events navigation unavailable");step++;}
            case 12->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.EVENTS)return;require(menu.triggerForTest("Create new event"),"Create Event unavailable");step++;}
            case 13->{if(!(client.currentScreen instanceof EventEditorScreen editor))return;editor.setDraftForTest("id","test:event_"+PHASE);editor.setDraftForTest("name","UI encounter Event");for(int i=0;i<4;i++)editor.navigateForTest(1);require(editor.pageForTest().equals("ACTIONS"),"Event Actions page unavailable");require(pressPrefix(editor,"Add action"),"Add action unavailable");require(pressPrefix(editor,"Spawn encounter group"),"Spawn encounter action unavailable");step++;}
            case 14->{if(!(client.currentScreen instanceof EventEditorScreen editor))return;require(pressPrefix(editor,"Encounter group: Choose"),"Encounter group picker unavailable");step++;}
            case 15->{if(!(client.currentScreen instanceof CatalogAddPopup popup))return;select(popup,group);if(client.currentScreen instanceof EventEditorScreen){frames=0;step++;}}
            case 16->{if(!(client.currentScreen instanceof EventEditorScreen editor))return;if(++frames==4)capture(client,PHASE+"-event-spawn-action.png");if(frames<4)return;var values=editor.valuesForTest();require(values.encounterActions().size()==1&&values.encounterActions().getFirst().groupId().equals(group)&&values.encounterActions().getFirst().current(),"Event spawn action did not retain the selected current group target");require(editor.pressForTest("Done"),"Encounter action Done unavailable");step++;}
            case 17->{if(!(client.currentScreen instanceof EventEditorScreen editor)||!editor.pageForTest().equals("ACTIONS"))return;var values=editor.valuesForTest();require(values.encounterActions().size()==1&&values.encounterActions().getFirst().groupId().equals(group),"Encounter action disappeared before Event save");require(editor.pressForTest("Create event"),"Create Event with encounter action unavailable");step++;}
            case 18->{if(!(client.currentScreen instanceof CoreMenuScreen menu)||menu.pending()||menu.state().page()!=Page.EVENTS)return;String eventId="test:event_"+PHASE;require(menu.state().selected().equals("cue:"+eventId),"saved Event was not selected in the parent menu");require(menu.state().detail()!=null&&menu.state().detail().facts().stream().anyMatch(fact->fact.label().equals("Event ID")&&fact.value().equals(eventId)),"saved Event detail is missing");if(!openerSent){openerSent=true;client.player.networkHandler.sendChatCommand("chronicle_encounters_trial ui_verify "+PHASE);}step++;}
            case 19->{if(messages.stream().noneMatch(value->value.contains("Encounter trial PASS ui_verify "+PHASE)))return;finish(client,true,"native Encounter groups/member/Point and Event spawn-action dialogs saved and verified without execution");}
            default->throw new IllegalStateException("unexpected encounter UI step");
        }
    }

    private static boolean pressPrefix(net.minecraft.client.gui.screen.Screen screen,String prefix){return screen.children().stream().filter(ButtonWidget.class::isInstance).map(ButtonWidget.class::cast).filter(button->button.visible&&button.active&&button.getMessage().getString().startsWith(prefix)).findFirst().map(button->{button.onPress(new net.minecraft.client.input.MouseInput(0,0));return true;}).orElse(false);}
    private static boolean pressSuffix(net.minecraft.client.gui.screen.Screen screen,String suffix){return screen.children().stream().filter(ButtonWidget.class::isInstance).map(ButtonWidget.class::cast).filter(button->button.visible&&button.active&&button.getMessage().getString().endsWith(suffix)).findFirst().map(button->{button.onPress(new net.minecraft.client.input.MouseInput(0,0));return true;}).orElse(false);}
    private static void select(CatalogAddPopup popup,String id){TextFieldWidget search=popup.children().stream().filter(TextFieldWidget.class::isInstance).map(TextFieldWidget.class::cast).findFirst().orElseThrow();if(!search.getText().equals(id)){search.setText(id);pressPrefix(popup,"Find");return;}CoreMenuScreen menu=popup.parentScreen() instanceof EncounterEditorScreen encounter?encounter.parentMenu():popup.parentScreen() instanceof EventEditorScreen event?event.parentMenu():popup.parentScreen() instanceof CoreMenuScreen direct?direct:null;if(menu==null||menu.state().picker()==null||!menu.state().picker().query().equals(id))return;String label=menu.state().picker().entries().stream().filter(entry->entry.id().equals(id)).map(io.github.chronicle.core.menu.CoreMenuModel.Entry::label).findFirst().orElse(null);if(label==null)return;ButtonWidget row=popup.children().stream().filter(ButtonWidget.class::isInstance).map(ButtonWidget.class::cast).filter(button->button.visible&&button.active&&(button.getMessage().getString().equals(label)||button.getMessage().getString().equals("> "+label))).findFirst().orElse(null);if(row==null)return;row.onPress(new net.minecraft.client.input.MouseInput(0,0));require(pressPrefix(popup,"Add"),"catalog Add unavailable");}
    private void capture(MinecraftClient client,String name){ScreenshotRecorder.saveScreenshot(output.getParent().toFile(),name,client.getFramebuffer(),1,ignored->{});}
    private static void require(boolean value,String message){if(!value)throw new IllegalStateException(message);}
    private void finish(MinecraftClient client,boolean pass,String detail){if(done)return;done=true;try{JsonObject value=new JsonObject();value.addProperty("result",pass?"PASS":"FAIL");value.addProperty("phase",PHASE);value.addProperty("detail",detail);JsonArray transcript=new JsonArray();messages.forEach(transcript::add);value.add("messages",transcript);Path proof=root.resolve(".encounter-actions-trial.json");if(Files.isRegularFile(proof))value.addProperty("serverProof",Files.readString(proof));Files.createDirectories(output.getParent());Files.writeString(output,value+"\n");}catch(Exception failure){ChronicleCore.LOGGER.error("Cannot write encounter smoke result",failure);}client.scheduleStop();}
}
